let alertWindow = 15m;
let baselineWindow = 24h;
let knownEndpoints = dynamic(['gcs-primary', 'telemetry-tap', 'sat-modem', 'qgc-local']);
let knownPorts = dynamic([5760, 5790, 14550, 14551]);
let KnownGCS = _GetWatchlist('C2_Whitelisted_GCS_List') | project GCS_IP;
// [블록 A] 비인가 엔드포인트/피어
let RogueEndpoint =
    UAVRouterStats_CL
    | where TimeGenerated > ago(alertWindow)
    | extend isUnknownEndpoint = EndpointName !in (knownEndpoints)
    | extend isUnknownPeer = PeerIp !in (KnownGCS)
    | where isUnknownEndpoint or isUnknownPeer
    | summarize MsgTxTotal = todouble(sum(MsgTx)), MsgRxTotal = todouble(sum(MsgRx)), FirstSeen = min(TimeGenerated) by EndpointName, PeerIp, PeerPort
    | extend TriggerReason = strcat('mavlink-router_비인가_엔드포인트_', EndpointName, '_PeerIp:', PeerIp)
    | extend Severity = 'High';
// [블록 B] MsgTx z-score 급증 (비인가 프록시 중계 트래픽 의심)
let TxAnomaly =
    UAVRouterStats_CL
    | where TimeGenerated > ago(baselineWindow)
    | make-series AvgMsgTx = avg(MsgTx) on TimeGenerated step 5m by EndpointName
    | extend (Anom, Score, Base) = series_decompose_anomalies(AvgMsgTx, 3.0)
    | project EndpointName, TimeGenerated, AvgMsgTx, Anom
    | mv-expand TimeGenerated to typeof(datetime), AvgMsgTx to typeof(double), Anom to typeof(double)
    | where TimeGenerated > ago(alertWindow) and Anom == 1
    | project TimeGenerated, EndpointName, MsgTxTotal = AvgMsgTx;
let EndpointPeer =
    UAVRouterStats_CL
    | where TimeGenerated > ago(alertWindow)
    | summarize arg_max(TimeGenerated, PeerIp, PeerPort) by EndpointName
    | project EndpointName, PeerIp, PeerPort;
let TxAnomalyWithPeer =
    TxAnomaly
    | join kind=inner (EndpointPeer) on EndpointName
    | extend MsgRxTotal = real(null)
    | extend TriggerReason = strcat('mavlink-router_MsgTx급증_비인가프록시의심_', EndpointName)
    | extend Severity = 'Medium'
    | project FirstSeen = TimeGenerated, EndpointName, PeerIp, PeerPort, MsgTxTotal, MsgRxTotal, TriggerReason, Severity;
// [블록 C] 비인가 PeerIp가 MAVLink 표준 포트로 직접 접속 (라우터 우회)
let UnknownConn =
    UAVDatalinkConn_CL
    | where TimeGenerated > ago(alertWindow)
    | where PeerIp !in (KnownGCS)
    | where LocalPort in (knownPorts)
    | summarize MsgTxTotal = todouble(count()), FirstSeen = min(TimeGenerated) by PeerIp, PeerPort = LocalPort
    | extend EndpointName = strcat('datalink-direct:', PeerIp)
    | extend MsgRxTotal = real(null)
    | extend TriggerReason = strcat('비인가IP_MAVLink포트_직접연결_PeerIp:', PeerIp, '_Port:', tostring(PeerPort))
    | extend Severity = 'Medium'
    | project FirstSeen, EndpointName, PeerIp, PeerPort, MsgTxTotal, MsgRxTotal, TriggerReason, Severity;
RogueEndpoint
| union TxAnomalyWithPeer
| union UnknownConn
| order by FirstSeen desc
